/**
 * Beat-sync music. Every track is an ORIGINAL loop generated by
 * scripts/generate-skate-sfx.mjs (drums + bass, synthesized from scratch) and
 * released under CC0 by the project, so it is safe for the App Store, social
 * re-posts and Content ID. BPM and first-beat are exact because we wrote them.
 * Licensed third-party tracks can be added here once a license is on file in
 * public/editor/CREDITS.md.
 */
export interface MusicTrack {
  id: string;
  title: string;
  mood: string;
  bpm: number;
  firstBeatSec: number;
  durationSec: number;
  src: string;
  license: "CC0 (original)";
}

const t = (id: string, title: string, mood: string, bpm: number): MusicTrack => ({
  id,
  title,
  mood,
  bpm,
  firstBeatSec: 0,
  durationSec: Number(((60 / bpm) * 4 * 8).toFixed(3)),
  src: `/editor/music/${id}.m4a`,
  license: "CC0 (original)",
});

export const MUSIC_TRACKS: readonly MusicTrack[] = [
  t("boom-bap-90", "Curb Cut", "Boom bap", 90),
  t("punk-170", "Kickflip Riot", "Fast punk", 170),
  t("lofi-75", "Late Session", "Lo-fi", 75),
  t("breaks-128", "Rail Ride", "Breakbeat", 128),
];

export function getTrack(id: string): MusicTrack | undefined {
  return MUSIC_TRACKS.find((x) => x.id === id);
}
